namespace sv_8f95b07221384c8d97be5041d78014b9.Services;

/// <summary>
/// Scoped service (per-circuit) that holds the current warehouse selection
/// and notifies all subscribers when it changes.
/// </summary>
public class WarehouseStateService
{
    private string _currentWarehouseId = "WH-001";

    public string CurrentWarehouseId
    {
        get => _currentWarehouseId;
        set
        {
            if (_currentWarehouseId != value)
            {
                _currentWarehouseId = value;
                NotifyStateChanged();
            }
        }
    }

    public string CurrentWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _currentWarehouseId)?.Name ?? "Unknown";

    public static IReadOnlyList<Warehouse> Warehouses { get; } = new List<Warehouse>
    {
        new("WH-001", "Warehouse A - Downtown"),
        new("WH-002", "Warehouse B - Airport"),
        new("WH-003", "Warehouse C - Harbor"),
        new("WH-004", "Warehouse D - Industrial Park")
    };

    public event Action? OnChange;

    private void NotifyStateChanged() => OnChange?.Invoke();
}

public record Warehouse(string Id, string Name);

namespace sv_8f95b07221384c8d97be5041d78014b9.Services;

/// <summary>
/// Scoped service (per-circuit) that tracks low-stock alert counts.
/// Provides polling capability and notifies all subscribers when data changes.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseStateService _warehouseState;
    private readonly Random _random = new();
    private Timer? _pollingTimer;
    private int _currentAlertCount;
    private int _activeSubscribers;

    public InventoryAlertService(WarehouseStateService warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += HandleWarehouseChanged;
    }

    public int CurrentAlertCount => _currentAlertCount;

    /// <summary>
    /// Fired when the alert count changes. All subscribed components receive this.
    /// </summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>
    /// Simulates a database query for items below minimum stock levels.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        var count = _random.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Starts polling every 10 seconds. Uses reference counting so multiple
    /// components can request polling without duplicating timers.
    /// </summary>
    public void StartPolling()
    {
        _activeSubscribers++;
        if (_pollingTimer == null)
        {
            _pollingTimer = new Timer(async _ => await PollAsync(), null, TimeSpan.Zero, TimeSpan.FromSeconds(10));
        }
    }

    /// <summary>
    /// Decrements the subscriber count. Stops polling when no subscribers remain.
    /// </summary>
    public void StopPolling()
    {
        _activeSubscribers = Math.Max(0, _activeSubscribers - 1);
        if (_activeSubscribers == 0)
        {
            _pollingTimer?.Dispose();
            _pollingTimer = null;
        }
    }

    private async Task PollAsync()
    {
        var newCount = await GetLowStockCountAsync(_warehouseState.CurrentWarehouseId);
        _currentAlertCount = newCount;
        await NotifySubscribersAsync();
    }

    private async void HandleWarehouseChanged()
    {
        // When warehouse changes, immediately re-poll for the new warehouse
        if (_pollingTimer != null)
        {
            await PollAsync();
        }
    }

    private async Task NotifySubscribersAsync()
    {
        if (OnAlertCountChanged != null)
        {
            await OnAlertCountChanged.Invoke();
        }
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= HandleWarehouseChanged;
        _pollingTimer?.Dispose();
    }
}

