@page "/dashboard"
@using sv_8f95b07221384c8d97be5041d78014b9.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Current Warehouse</h5>
                <p class="card-text fs-4">@WarehouseState.CurrentWarehouseName</p>
                <p class="text-muted">ID: @WarehouseState.CurrentWarehouseId</p>
            </div>
        </div>
    </div>
    <div class="col-md-6">
        <div class="card @(AlertService.CurrentAlertCount > 5 ? "border-danger" : "border-warning")">
            <div class="card-body">
                <h5 class="card-title">Low Stock Alerts</h5>
                <p class="card-text fs-1 @(AlertService.CurrentAlertCount > 5 ? "text-danger" : "text-warning")">
                    @AlertService.CurrentAlertCount
                </p>
                <p class="text-muted">Items below minimum level (refreshes every 10s)</p>
            </div>
        </div>
    </div>
</div>

<div class="row">
    <div class="col-12">
        <div class="card">
            <div class="card-body">
                <h5 class="card-title">Activity Log</h5>
                <ul class="list-group list-group-flush">
                    @foreach (var entry in _activityLog.TakeLast(10).Reverse())
                    {
                        <li class="list-group-item">@entry</li>
                    }
                </ul>
            </div>
        </div>
    </div>
</div>

@code {
    private readonly List<string> _activityLog = new();

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += HandleWarehouseChanged;
        AlertService.OnAlertCountChanged += HandleAlertCountChanged;

        // Start polling when dashboard is visible
        AlertService.StartPolling();

        _activityLog.Add($"[{DateTime.Now:HH:mm:ss}] Dashboard opened for {WarehouseState.CurrentWarehouseName}");
    }

    private void HandleWarehouseChanged()
    {
        _activityLog.Add($"[{DateTime.Now:HH:mm:ss}] Switched to {WarehouseState.CurrentWarehouseName}");
        InvokeAsync(StateHasChanged);
    }

    private async Task HandleAlertCountChanged()
    {
        _activityLog.Add($"[{DateTime.Now:HH:mm:ss}] Alert count updated: {AlertService.CurrentAlertCount} low-stock items at {WarehouseState.CurrentWarehouseName}");
        await InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= HandleWarehouseChanged;
        AlertService.OnAlertCountChanged -= HandleAlertCountChanged;

        // Stop polling when user leaves the page
        AlertService.StopPolling();
    }
}

